node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Search for PROD-2028EE or VoltForge in the raw bytes
const text = data.toString('utf8');
const idx = text.indexOf('PROD-2028EE');
if (idx >= 0) {
  console.log('Found PROD-2028EE at index', idx);
  console.log(text.substring(Math.max(0, idx-200), idx+500));
} else {
  console.log('PROD-2028EE not found');
}
const idx2 = text.indexOf('VoltForge');
if (idx2 >= 0) {
  console.log('Found VoltForge at index', idx2);
  console.log(text.substring(Math.max(0, idx2-200), idx2+500));
} else {
  console.log('VoltForge not found');
}
" 2>&1

